7	import { liveLinkOf, rememberLiveLink } from "../live/route.ts";
8	import { useHosted } from "../hosted/HostedProvider.tsx";
9	import { useSync } from "../sync/SyncProvider.tsx";
10	import type { StoredRun } from "../storage/db.ts";
11	import { useProfile } from "../sync/useProfile.ts";
12	import { useReachable } from "./useReachable.ts";
13	import { controlAddress } from "./controlAddress.ts";
14	import { useAttachedDecks } from "./useAttachedTools.ts";
15	
16	/**
17	 * Who is at the table, and how to ask someone else.
18	 *
19	 * The members come with the run from the server; the invitations and the
20	 * people list are asked for when the panel opens, since only the owner
21	 * sees them and they change rarely. Inviting is an address and a role, with
22	 * the people this account has played with offered as the address is typed.
23	 * Nothing here is available without an account, and the panel says so
24	 * rather than showing controls that cannot work.
25	 */
26	export function Members({ pack, run }: { pack: Pack; run: StoredRun }) {
27	  const account = useAccount();
28	  const api = useApi();
29	  const hosted = useHosted();
30	  const sync = useSync();
31	  const me = account.status === "signed-in" ? account.user.id : null;
32	  const noun = pack.vocabulary.run.one.toLowerCase();
33	  const [upgrade, setUpgrade] = useState<string | null>(null);
34	  const { profile } = useProfile();
35	  const reach = useReachable(api, run);
36	  const decks = useAttachedDecks(run.runId);
37	  const [copiedAddress, setCopiedAddress] = useState<string | null>(null);
38	  const owner = run.role === "owner";
39	
40	  /**
41	   * Who is at the table, with yourself in it.
42	   *
43	   * The server's member list is the people it knows about, which for a
44	   * run nobody has been invited to is nobody at all -- so the panel
45	   * showed an empty box to the one person certainly sitting there. A
46	   * solo run has a player; it just has not had to tell anybody.
47	   */
48	  const listed: SessionMember[] = run.members ?? [];
49	  const mine = profile?.handle?.trim() || profile?.name?.trim() || "You";
50	  const members: SessionMember[] =
51	    me && !listed.some((m) => m.sub === me)
52	      ? [{ sub: me, name: mine, role: owner ? "owner" : (run.role ?? "player") } as SessionMember, ...listed]
53	      : listed;
54	
55	  /**
56	   * The address a tool dials for one person, or for the table.
57	   *
58	   * Here rather than only behind Settings because this is the list of
59	   * who is playing, and setting a tool up is a thing you do per person
60	   * while looking at exactly that.
61	   */
62	  const copyAddress = async (seat: string | undefined, id: string) => {
63	    const address = controlAddress({ key: reach.key, runId: run.runId, seat });
64	    try {
65	      await navigator.clipboard.writeText(address);
66	      setCopiedAddress(id);
67	      window.setTimeout(() => setCopiedAddress((was) => (was === id ? null : was)), 1500);
68	    } catch {
69	      // A clipboard that refuses is the browser's call; the address is
70	      // still on screen to read.
71	    }
72	  };
73	
74	  const [invites, setInvites] = useState<Invite[]>([]);
75	  const [people, setPeople] = useState<Person[]>([]);
76	  const [email, setEmail] = useState("");
77	  const [role, setRole] = useState<"player" | "viewer">("player");
78	  const [busy, setBusy] = useState(false);
79	  const [note, setNote] = useState<string | null>(null);
80	  const [liveLink, setLiveLink] = useState<string | null>(() => liveLinkOf(run.runId));
81	  const [liveNote, setLiveNote] = useState<string | null>(null);
82	  const [copied, setCopied] = useState(false);
83	  const shared = Boolean(liveLink) || run.shared === true;
84	  const [reactions, setReactions] = useState<Reaction[]>([]);
85	  const [reactedAt, setReactedAt] = useState(0);
86	
87	  // What the watchers and the table sent: read when the panel opens, on
88	  // every pull of this run (the socket rings for a reaction), and every so
89	  // often.
90	  useEffect(() => {
91	    if (!api) return;
92	    let live = true;
93	    const read = () =>
94	      void api.reactions(run.runId).then(
95	        (r) => live && setReactions(r),
96	        () => {},
97	      );
98	    read();
99	    const every = window.setInterval(read, 15_000);
100	    const off = syncBus.subscribe((news) => {
101	      if (news.t === "pulled" && news.kind === "run" && news.ids.includes(run.runId)) read();
102	    });
103	    return () => {
104	      live = false;
105	      window.clearInterval(every);
106	      off();
107	    };
108	  }, [api, shared, run.runId]);
109	
110	  const refresh = () => {
111	    if (!api || !owner) return;
112	    void api.listInvites(run.runId).then(setInvites, () => {});
113	    void api.people().then(setPeople, () => {});
114	  };
115	  useEffect(refresh, [api, owner, run.runId]);
116	
117	  const heading = (
118	    <summary>
119	      <h3 className="sectionTitle">
120	        People <span className="muted">at the table</span>
121	      </h3>
122	    </summary>
123	  );
124	
125	  if (!api) {
126	    return (
127	      <details className="panel people">
128	        {heading}
129	        <div className="peopleBody">
130	          <p className="muted small">Sign in to share this {noun} with someone.</p>
131	        </div>
132	      </details>
133	    );
134	  }
135	
136	  const invite = async () => {
137	    const to = email.trim();
138	    if (!to || busy) return;
139	    setBusy(true);
140	    setNote(null);
141	    try {
142	      await api.createInvite(run.runId, to, role);
143	      setEmail("");
144	      setNote(`Sent to ${to}. The link works for seven days.`);
145	      refresh();
146	    } catch (error) {
147	      if (error instanceof PlanError) setUpgrade(error.message);
148	      else setNote(error instanceof Error && error.message ? error.message : "That did not send. Try again in a moment.");
149	    } finally {
150	      setBusy(false);
151	    }
152	  };
153	
154	  const pending = invites.filter((i) => !i.accepted);
155	  const react = (emoji: string) => {
156	    if (reactedAt > Date.now()) return;
157	    setReactedAt(Date.now() + 1000);
158	    void api.react(run.runId, emoji).then(setReactions, () => {});
159	  };
160	
161	  /**
162	   * Where the run stands with the account, said plainly. A run the server
163	   * has never seen has no role yet; whether it is on its way depends on
164	   * this device's sync switch, which is the thing to offer.
165	   */
166	  const reached = run.role !== undefined;
167	  const company = members.some((m) => m.sub !== me) || pending.length > 0;
168	
169	  return (
170	    <details className="panel people members" open={company}>
171	      {heading}
